import { useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import {
  BOUNTY_STATUS_LABELS,
  upsertBountyFinding,
  type BountyFinding,
  type BountyFindingStatus,
  type BountyProgram,
} from "@/lib/redteam/bounty-store";
import { downloadBountyReport } from "@/lib/redteam/bounty-report";
import { Trash2, Edit, FileText, Filter, DollarSign } from "lucide-react";

const SEV_STYLE: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/30",
  high: "bg-orange-500/15 text-orange-400 border-orange-500/30",
  medium: "bg-amber-500/15 text-amber-400 border-amber-500/30",
  low: "bg-blue-500/15 text-blue-400 border-blue-500/30",
  info: "bg-slate-500/15 text-slate-400 border-slate-500/30",
};

const STATUSES: BountyFindingStatus[] = [
  "discovered", "validating", "report-ready", "submitted", "triaged",
  "accepted", "paid", "duplicate", "informative", "wont-fix",
];

type Props = {
  findings: BountyFinding[];
  programs: BountyProgram[];
  onSave: (f: Parameters<typeof upsertBountyFinding>[0]) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
};

export function BountyFindingsBoard({ findings, programs, onSave, onDelete }: Props) {
  const [severityFilter, setSeverityFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [editFinding, setEditFinding] = useState<BountyFinding | null>(null);
  const [draft, setDraft] = useState<Partial<BountyFinding>>({});

  const programMap = useMemo(
    () => Object.fromEntries(programs.map((p) => [p.id, p])),
    [programs],
  );

  const filtered = useMemo(() => {
    return findings.filter((f) => {
      if (severityFilter !== "all" && f.severity !== severityFilter) return false;
      if (statusFilter !== "all" && f.status !== statusFilter) return false;
      return true;
    });
  }, [findings, severityFilter, statusFilter]);

  const openEdit = (f: BountyFinding) => {
    setEditFinding(f);
    setDraft({ ...f });
  };

  const submitEdit = async () => {
    if (!editFinding || !draft.programId) return;
    await onSave({
      id: editFinding.id,
      programId: draft.programId,
      title: draft.title ?? "",
      severity: draft.severity ?? "medium",
      vulnType: draft.vulnType ?? "",
      status: draft.status ?? "discovered",
      target: draft.target ?? "",
      description: draft.description ?? "",
      stepsToReproduce: draft.stepsToReproduce ?? "",
      impact: draft.impact ?? "",
      evidence: draft.evidence ?? "",
      remediation: draft.remediation ?? "",
      bountyEstimate: draft.bountyEstimate ?? null,
      bountyPaid: draft.bountyPaid ?? null,
      reportedAt: draft.reportedAt ?? null,
      paidAt: draft.paidAt ?? null,
      platformTicketId: draft.platformTicketId ?? "",
      scanId: draft.scanId ?? null,
    });
    setEditFinding(null);
  };

  const markPaid = async (f: BountyFinding) => {
    const paid = prompt("Bounty amount received (USD):", String(f.bountyEstimate ?? ""));
    if (paid == null) return;
    const amount = parseFloat(paid);
    await onSave({
      ...f,
      status: "paid",
      bountyPaid: Number.isFinite(amount) ? amount : f.bountyPaid,
      paidAt: new Date().toISOString(),
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2 items-center">
        <Filter className="h-4 w-4 text-muted-foreground" />
        <Select value={severityFilter} onValueChange={setSeverityFilter}>
          <SelectTrigger className="w-[130px] h-8 text-xs"><SelectValue placeholder="Severity" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All severity</SelectItem>
            <SelectItem value="critical">Critical</SelectItem>
            <SelectItem value="high">High</SelectItem>
            <SelectItem value="medium">Medium</SelectItem>
            <SelectItem value="low">Low</SelectItem>
          </SelectContent>
        </Select>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[150px] h-8 text-xs"><SelectValue placeholder="Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All status</SelectItem>
            {STATUSES.map((s) => (
              <SelectItem key={s} value={s}>{BOUNTY_STATUS_LABELS[s]}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Badge variant="secondary" className="text-xs">{filtered.length} findings</Badge>
      </div>

      {filtered.length === 0 ? (
        <Card className="border-dashed">
          <CardContent className="py-10 text-center text-sm text-muted-foreground">
            No findings yet. Run a hunt or import from Pentest Agent.
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-3">
          {filtered.map((f) => (
            <Card key={f.id} className="border-border/60">
              <CardHeader className="pb-2">
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <div className="space-y-1 min-w-0 flex-1">
                    <CardTitle className="text-sm leading-tight">{f.title}</CardTitle>
                    <p className="text-xs text-muted-foreground font-mono truncate">{f.target}</p>
                  </div>
                  <div className="flex flex-wrap gap-1.5 shrink-0">
                    <Badge className={SEV_STYLE[f.severity]}>{f.severity}</Badge>
                    <Badge variant="outline" className="text-[10px]">
                      {BOUNTY_STATUS_LABELS[f.status]}
                    </Badge>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="pt-0 space-y-2">
                <p className="text-xs text-muted-foreground line-clamp-2">{f.description}</p>
                <div className="flex flex-wrap gap-1.5 text-[10px] text-muted-foreground">
                  <span>{programMap[f.programId]?.name ?? "Unknown program"}</span>
                  {f.vulnType && <span>· {f.vulnType}</span>}
                  {f.bountyEstimate != null && (
                    <span className="text-amber-400">· est. ${f.bountyEstimate}</span>
                  )}
                  {f.bountyPaid != null && (
                    <span className="text-emerald-400">· paid ${f.bountyPaid}</span>
                  )}
                </div>
                <div className="flex flex-wrap gap-1.5 pt-1">
                  <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => openEdit(f)}>
                    <Edit className="h-3 w-3" /> Edit
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-7 text-xs gap-1"
                    onClick={() => downloadBountyReport(f, programMap[f.programId] ?? null, "hackerone")}
                  >
                    <FileText className="h-3 w-3" /> H1 report
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-7 text-xs gap-1"
                    onClick={() => downloadBountyReport(f, programMap[f.programId] ?? null, "bugcrowd")}
                  >
                    <FileText className="h-3 w-3" /> BC report
                  </Button>
                  {f.status !== "paid" && (
                    <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => void markPaid(f)}>
                      <DollarSign className="h-3 w-3" /> Mark paid
                    </Button>
                  )}
                  <Button
                    size="sm"
                    variant="ghost"
                    className="h-7 text-xs text-red-400"
                    onClick={() => void onDelete(f.id)}
                  >
                    <Trash2 className="h-3 w-3" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Dialog open={!!editFinding} onOpenChange={(o) => !o && setEditFinding(null)}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Edit finding</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div className="space-y-1">
              <Label className="text-xs">Title</Label>
              <Input value={draft.title ?? ""} onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))} />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Severity</Label>
                <Select value={draft.severity} onValueChange={(v) => setDraft((d) => ({ ...d, severity: v as BountyFinding["severity"] }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {["critical", "high", "medium", "low", "info"].map((s) => (
                      <SelectItem key={s} value={s}>{s}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Status</Label>
                <Select value={draft.status} onValueChange={(v) => setDraft((d) => ({ ...d, status: v as BountyFindingStatus }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {STATUSES.map((s) => (
                      <SelectItem key={s} value={s}>{BOUNTY_STATUS_LABELS[s]}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Impact</Label>
              <Textarea rows={2} value={draft.impact ?? ""} onChange={(e) => setDraft((d) => ({ ...d, impact: e.target.value }))} />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Steps to reproduce</Label>
              <Textarea rows={3} value={draft.stepsToReproduce ?? ""} onChange={(e) => setDraft((d) => ({ ...d, stepsToReproduce: e.target.value }))} className="font-mono text-xs" />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Evidence</Label>
              <Textarea rows={2} value={draft.evidence ?? ""} onChange={(e) => setDraft((d) => ({ ...d, evidence: e.target.value }))} className="font-mono text-xs" />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Estimate (USD)</Label>
                <Input
                  type="number"
                  value={draft.bountyEstimate ?? ""}
                  onChange={(e) => setDraft((d) => ({ ...d, bountyEstimate: e.target.value ? Number(e.target.value) : null }))}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Platform ticket #</Label>
                <Input value={draft.platformTicketId ?? ""} onChange={(e) => setDraft((d) => ({ ...d, platformTicketId: e.target.value }))} />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditFinding(null)}>Cancel</Button>
            <Button onClick={() => void submitEdit()}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
