import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  DollarSign, Target, AlertTriangle, Send, CheckCircle2, TrendingUp, Bug,
} from "lucide-react";
import type { BountyHunterStats } from "@/lib/redteam/bounty-store";

type Props = {
  stats: BountyHunterStats;
  loading?: boolean;
};

export function BountyHunterDashboard({ stats, loading }: Props) {
  const cards = [
    {
      label: "Critical open",
      value: stats.criticalOpen,
      icon: AlertTriangle,
      color: "text-red-400",
      hint: "Validate & report first",
    },
    {
      label: "High open",
      value: stats.highOpen,
      icon: Bug,
      color: "text-orange-400",
      hint: "Triage for submission",
    },
    {
      label: "Submitted",
      value: stats.submitted,
      icon: Send,
      color: "text-cyan-400",
      hint: "Awaiting platform triage",
    },
    {
      label: "Paid bounties",
      value: stats.paid,
      icon: CheckCircle2,
      color: "text-emerald-400",
      hint: `${stats.accepted} accepted total`,
    },
    {
      label: "Earnings (USD)",
      value: stats.earningsUsd > 0 ? `$${stats.earningsUsd.toLocaleString()}` : "$0",
      icon: DollarSign,
      color: "text-emerald-300",
      hint: "From paid findings you logged",
    },
    {
      label: "Pipeline (USD)",
      value: stats.pipelineUsd > 0 ? `$${stats.pipelineUsd.toLocaleString()}` : "$0",
      icon: TrendingUp,
      color: "text-amber-300",
      hint: "Estimated from submitted/accepted",
    },
    {
      label: "Programs",
      value: stats.programs,
      icon: Target,
      color: "text-violet-400",
      hint: `${stats.totalFindings} findings tracked`,
    },
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-3">
      {cards.map((c) => (
        <Card key={c.label} className="border-border/60 bg-card/50">
          <CardHeader className="pb-1 pt-3 px-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-[11px] font-medium text-muted-foreground uppercase tracking-wide">
                {c.label}
              </CardTitle>
              <c.icon className={`h-3.5 w-3.5 ${c.color}`} />
            </div>
          </CardHeader>
          <CardContent className="px-3 pb-3">
            <p className={`text-xl font-bold tabular-nums ${loading ? "opacity-40" : ""}`}>
              {loading ? "—" : c.value}
            </p>
            <p className="text-[10px] text-muted-foreground mt-0.5">{c.hint}</p>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

export function BountyPriorityBanner({ criticalOpen, highOpen }: { criticalOpen: number; highOpen: number }) {
  if (criticalOpen === 0 && highOpen === 0) return null;
  return (
    <Card className="border-red-500/30 bg-gradient-to-r from-red-500/10 to-orange-500/5">
      <CardContent className="py-3 flex flex-wrap items-center gap-3">
        <AlertTriangle className="h-5 w-5 text-red-400 shrink-0" />
        <div className="flex-1 min-w-[200px]">
          <p className="text-sm font-medium text-red-300">
            {criticalOpen > 0
              ? `${criticalOpen} critical finding${criticalOpen > 1 ? "s" : ""} need validation`
              : `${highOpen} high-severity finding${highOpen > 1 ? "s" : ""} in queue`}
          </p>
          <p className="text-xs text-muted-foreground">
            Focus on critical/high — validate PoC, write impact, submit before duplicates.
          </p>
        </div>
        {criticalOpen > 0 && (
          <Badge className="bg-red-500/20 text-red-300 border-red-500/40">
            {criticalOpen} CRITICAL
          </Badge>
        )}
      </CardContent>
    </Card>
  );
}
