import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { runPentestScan } from "@/lib/redteam/pentest-client";
import { parseScopeToUrls } from "@/lib/redteam/engagement-orchestrator";
import {
  isTargetInScope,
  type BountyProgram,
} from "@/lib/redteam/bounty-store";
import type { PentestDepth, PentestReport } from "@/lib/redteam/pentest-types";
import { Loader2, Play, Shield, Target, Zap } from "lucide-react";

type Props = {
  programs: BountyProgram[];
  activeProgramId: string | null;
  onProgramChange: (id: string) => void;
  onScanComplete: (report: PentestReport) => void;
};

export function BountyHuntPipeline({
  programs,
  activeProgramId,
  onProgramChange,
  onScanComplete,
}: Props) {
  const { toast } = useToast();
  const [authorized, setAuthorized] = useState(false);
  const [target, setTarget] = useState("");
  const [depth, setDepth] = useState<PentestDepth>("standard");
  const [scanAllScope, setScanAllScope] = useState(false);
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0, current: "" });

  const program = programs.find((p) => p.id === activeProgramId) ?? null;
  const scopeCheck = program ? isTargetInScope(target, program.inScope) : null;

  const runHunt = async () => {
    if (!authorized) {
      toast({ title: "Authorization required", description: "Confirm you have program permission.", variant: "destructive" });
      return;
    }
    if (!program) {
      toast({ title: "Select a program", variant: "destructive" });
      return;
    }

    const urls = scanAllScope && program.inScope.length
      ? parseScopeToUrls(program.inScope.join("\n"))
      : target.trim()
        ? parseScopeToUrls(target)
        : [];

    if (!urls.length) {
      toast({ title: "No targets", description: "Enter a URL or add in-scope domains to the program.", variant: "destructive" });
      return;
    }

    setRunning(true);
    setProgress({ done: 0, total: urls.length, current: urls[0] });
    let lastReport: PentestReport | null = null;

    try {
      for (let i = 0; i < urls.length; i++) {
        const url = urls[i];
        setProgress({ done: i, total: urls.length, current: url });
        const { report } = await runPentestScan({
          url,
          depth,
          authorized: true,
          saveEngagement: true,
          clientName: program.name,
        });
        lastReport = report;
        onScanComplete(report);
        setProgress({ done: i + 1, total: urls.length, current: url });
      }

      const crit = lastReport?.metrics.critical ?? 0;
      const high = lastReport?.metrics.high ?? 0;
      toast({
        title: "Hunt pass complete",
        description: `Scanned ${urls.length} target(s). Last: ${crit} critical, ${high} high.`,
      });
    } catch (e) {
      toast({
        title: "Scan failed",
        description: e instanceof Error ? e.message : "Unknown error",
        variant: "destructive",
      });
    } finally {
      setRunning(false);
    }
  };

  return (
    <Card className="border-rose-500/25">
      <CardHeader>
        <CardTitle className="text-base flex items-center gap-2">
          <Zap className="h-4 w-4 text-rose-400" /> Hunt pipeline
        </CardTitle>
        <CardDescription>
          Passive automated scan via Pentest Agent — imports critical/high into your bounty queue.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid sm:grid-cols-2 gap-3">
          <div className="space-y-1.5">
            <Label className="text-xs">Active program</Label>
            <Select value={activeProgramId ?? ""} onValueChange={onProgramChange}>
              <SelectTrigger>
                <SelectValue placeholder="Select program…" />
              </SelectTrigger>
              <SelectContent>
                {programs.map((p) => (
                  <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            {programs.length === 0 && (
              <p className="text-[10px] text-amber-400">Create a program in the Programs tab first.</p>
            )}
          </div>
          <div className="space-y-1.5">
            <Label className="text-xs">Scan depth</Label>
            <Select value={depth} onValueChange={(v) => setDepth(v as PentestDepth)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="quick">Quick (~30s)</SelectItem>
                <SelectItem value="standard">Standard</SelectItem>
                <SelectItem value="deep">Deep</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="space-y-1.5">
          <Label className="text-xs">Target URL or domain</Label>
          <div className="flex flex-wrap gap-2">
            <Input
              placeholder="https://app.example.com"
              value={target}
              onChange={(e) => setTarget(e.target.value)}
              disabled={scanAllScope || running}
              className="font-mono text-sm flex-1 min-w-[200px]"
            />
            {scopeCheck === true && <Badge className="bg-emerald-500/20 text-emerald-400">In scope</Badge>}
            {scopeCheck === false && (
              <Badge variant="destructive" className="text-xs">Out of scope list</Badge>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Checkbox
            id="scan-all"
            checked={scanAllScope}
            onCheckedChange={(c) => setScanAllScope(c === true)}
            disabled={running || !program?.inScope.length}
          />
          <Label htmlFor="scan-all" className="text-xs cursor-pointer">
            Scan all in-scope URLs from program ({program?.inScope.length ?? 0} patterns)
          </Label>
        </div>

        <div className="flex items-start gap-2 rounded-lg border border-amber-500/30 bg-amber-500/5 p-3">
          <Checkbox
            id="roe"
            checked={authorized}
            onCheckedChange={(c) => setAuthorized(c === true)}
            disabled={running}
          />
          <Label htmlFor="roe" className="text-xs leading-relaxed cursor-pointer">
            <Shield className="h-3.5 w-3.5 inline mr-1 text-amber-400" />
            I have written authorization (bug bounty program rules, asset ownership, or signed ROE) to test these targets.
          </Label>
        </div>

        {running && (
          <div className="space-y-2">
            <Progress value={(progress.done / Math.max(progress.total, 1)) * 100} />
            <p className="text-xs text-muted-foreground font-mono truncate">
              {progress.done}/{progress.total} — {progress.current}
            </p>
          </div>
        )}

        <Button onClick={() => void runHunt()} disabled={running || !programs.length} className="gap-2">
          {running ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
          Run passive hunt
        </Button>

        {program && program.inScope.length > 0 && (
          <div className="text-[10px] text-muted-foreground">
            <Target className="h-3 w-3 inline mr-1" />
            Scope: {program.inScope.slice(0, 5).join(", ")}
            {program.inScope.length > 5 ? ` +${program.inScope.length - 5} more` : ""}
          </div>
        )}
      </CardContent>
    </Card>
  );
}
