import { useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import { useBountyHunter } from "@/hooks/useBountyHunter";
import { BountyHunterDashboard, BountyPriorityBanner } from "@/components/redteam/BountyHunterDashboard";
import { BountyHuntPipeline } from "@/components/redteam/BountyHuntPipeline";
import { BountyFindingsBoard } from "@/components/redteam/BountyFindingsBoard";
import { BountyProgramManager } from "@/components/redteam/BountyProgramManager";
import { BugBountyWorkbench } from "@/components/redteam/BugBountyWorkbench";
import type { PentestReport } from "@/lib/redteam/pentest-types";
import {
  Bug, Crosshair, DollarSign, FileText, Target, Wrench, Zap,
} from "lucide-react";

export default function BountyHunterPage() {
  const { toast } = useToast();
  const {
    programs,
    findings,
    stats,
    loading,
    saveProgram,
    removeProgram,
    saveFinding,
    removeFinding,
    importFromScan,
  } = useBountyHunter();

  const [activeProgramId, setActiveProgramId] = useState<string | null>(null);
  const [lastScan, setLastScan] = useState<PentestReport | null>(null);

  const effectiveProgramId = activeProgramId ?? programs[0]?.id ?? null;

  const handleScanComplete = async (report: PentestReport) => {
    setLastScan(report);
    if (!effectiveProgramId) {
      toast({
        title: "Scan done — no program selected",
        description: `${report.metrics.critical} critical, ${report.metrics.high} high. Create a program to import.`,
      });
      return;
    }
    const imported = await importFromScan(report, effectiveProgramId, "high");
    if (imported.length) {
      toast({
        title: `Imported ${imported.length} finding(s)`,
        description: "Critical/high added to your bounty queue.",
      });
    }
  };

  return (
    <div className="space-y-6 p-4 md:p-6 max-w-7xl mx-auto">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Bug className="h-6 w-6 text-amber-400" />
            <h1 className="text-2xl font-bold">Bug Bounty Hunter</h1>
          </div>
          <p className="text-sm text-muted-foreground max-w-2xl">
            Find critical vulnerabilities, track submissions, and log earnings — authorized programs only.
            Lives in the Offensive block; separate from threat intel feeds.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button size="sm" variant="outline" asChild>
            <Link to="/offensive/pentest-agent">
              <Zap className="h-3.5 w-3.5 mr-1.5" /> Pentest Agent
            </Link>
          </Button>
          <Button size="sm" variant="outline" asChild>
            <Link to="/offensive/lab?tab=bounty">
              <Wrench className="h-3.5 w-3.5 mr-1.5" /> Tool lab
            </Link>
          </Button>
        </div>
      </div>

      <BountyPriorityBanner criticalOpen={stats.criticalOpen} highOpen={stats.highOpen} />
      <BountyHunterDashboard stats={stats} loading={loading} />

      <Tabs defaultValue="hunt">
        <TabsList className="flex flex-wrap h-auto gap-1">
          <TabsTrigger value="hunt" className="gap-1.5">
            <Crosshair className="h-3.5 w-3.5" /> Hunt
          </TabsTrigger>
          <TabsTrigger value="findings" className="gap-1.5">
            <FileText className="h-3.5 w-3.5" /> Findings
            {stats.totalFindings > 0 && (
              <span className="text-[10px] bg-secondary px-1 rounded">{stats.totalFindings}</span>
            )}
          </TabsTrigger>
          <TabsTrigger value="programs" className="gap-1.5">
            <Target className="h-3.5 w-3.5" /> Programs
          </TabsTrigger>
          <TabsTrigger value="tools" className="gap-1.5">
            <Wrench className="h-3.5 w-3.5" /> Tools
          </TabsTrigger>
          <TabsTrigger value="earnings" className="gap-1.5">
            <DollarSign className="h-3.5 w-3.5" /> Earnings
          </TabsTrigger>
        </TabsList>

        <TabsContent value="hunt" className="mt-4 space-y-4">
          <BountyHuntPipeline
            programs={programs}
            activeProgramId={effectiveProgramId}
            onProgramChange={setActiveProgramId}
            onScanComplete={(r) => void handleScanComplete(r)}
          />
          {lastScan && (
            <Card className="border-border/60">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Last scan — {lastScan.hostname}</CardTitle>
                <CardDescription>
                  Grade {lastScan.grade} · {lastScan.metrics.critical} critical · {lastScan.metrics.high} high
                </CardDescription>
              </CardHeader>
              <CardContent className="flex flex-wrap gap-2">
                <Button size="sm" variant="outline" asChild>
                  <Link to={`/offensive/pentest-agent`}>Full report</Link>
                </Button>
                <Button
                  size="sm"
                  disabled={!effectiveProgramId}
                  onClick={() => void handleScanComplete(lastScan)}
                >
                  Re-import critical/high
                </Button>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="findings" className="mt-4">
          <BountyFindingsBoard
            findings={findings}
            programs={programs}
            onSave={saveFinding}
            onDelete={removeFinding}
          />
        </TabsContent>

        <TabsContent value="programs" className="mt-4">
          <BountyProgramManager
            programs={programs}
            onSave={saveProgram}
            onDelete={removeProgram}
            activeId={effectiveProgramId}
            onSelect={setActiveProgramId}
          />
        </TabsContent>

        <TabsContent value="tools" className="mt-4">
          <BugBountyWorkbench />
        </TabsContent>

        <TabsContent value="earnings" className="mt-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Earnings tracker</CardTitle>
              <CardDescription>
                Real numbers from findings you mark as paid — not estimated platform data.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid sm:grid-cols-3 gap-4">
                <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-4">
                  <p className="text-xs text-muted-foreground">Total paid</p>
                  <p className="text-2xl font-bold text-emerald-400">
                    ${stats.earningsUsd.toLocaleString()}
                  </p>
                </div>
                <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-4">
                  <p className="text-xs text-muted-foreground">Pipeline (est.)</p>
                  <p className="text-2xl font-bold text-amber-300">
                    ${stats.pipelineUsd.toLocaleString()}
                  </p>
                </div>
                <div className="rounded-lg border border-border/60 p-4">
                  <p className="text-xs text-muted-foreground">Paid reports</p>
                  <p className="text-2xl font-bold">{stats.paid}</p>
                </div>
              </div>
              <p className="text-xs text-muted-foreground">
                Mark findings as paid in the Findings tab after platform payout. Estimates use VRT-aligned
                defaults you can override per finding.
              </p>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
