import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import {
  BOUNTY_PLATFORM_LABELS,
  type BountyPlatform,
  type BountyProgram,
} from "@/lib/redteam/bounty-store";
import { Plus, Trash2, ExternalLink, Target } from "lucide-react";

type Props = {
  programs: BountyProgram[];
  onSave: (p: Omit<BountyProgram, "id" | "createdAt" | "updatedAt"> & { id?: string }) => Promise<BountyProgram>;
  onDelete: (id: string) => Promise<void>;
  activeId: string | null;
  onSelect: (id: string) => void;
};

const PLATFORMS: BountyPlatform[] = [
  "hackerone", "bugcrowd", "intigriti", "yeswehack", "synack", "self", "other",
];

export function BountyProgramManager({ programs, onSave, onDelete, activeId, onSelect }: Props) {
  const [editing, setEditing] = useState<BountyProgram | "new" | null>(null);
  const [name, setName] = useState("");
  const [platform, setPlatform] = useState<BountyPlatform>("hackerone");
  const [platformUrl, setPlatformUrl] = useState("");
  const [inScope, setInScope] = useState("");
  const [outOfScope, setOutOfScope] = useState("");
  const [notes, setNotes] = useState("");

  const resetForm = () => {
    setEditing(null);
    setName("");
    setPlatform("hackerone");
    setPlatformUrl("");
    setInScope("");
    setOutOfScope("");
    setNotes("");
  };

  const startNew = () => {
    resetForm();
    setEditing("new");
  };

  const startEdit = (p: BountyProgram) => {
    setEditing(p);
    setName(p.name);
    setPlatform(p.platform);
    setPlatformUrl(p.platformUrl);
    setInScope(p.inScope.join("\n"));
    setOutOfScope(p.outOfScope.join("\n"));
    setNotes(p.notes);
  };

  const submit = async () => {
    if (!name.trim()) return;
    const saved = await onSave({
      id: editing !== "new" && editing ? editing.id : undefined,
      name,
      platform,
      platformUrl,
      inScope: inScope.split("\n").map((s) => s.trim()).filter(Boolean),
      outOfScope: outOfScope.split("\n").map((s) => s.trim()).filter(Boolean),
      notes,
    });
    onSelect(saved.id);
    resetForm();
  };

  return (
    <div className="grid lg:grid-cols-2 gap-4">
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-medium">Your programs</h3>
          <Button size="sm" onClick={startNew} className="gap-1">
            <Plus className="h-3.5 w-3.5" /> Add program
          </Button>
        </div>
        {programs.length === 0 ? (
          <Card className="border-dashed">
            <CardContent className="py-8 text-center text-sm text-muted-foreground">
              Add HackerOne, Bugcrowd, or private programs with scope rules.
            </CardContent>
          </Card>
        ) : (
          programs.map((p) => (
            <Card
              key={p.id}
              className={`cursor-pointer transition-colors ${activeId === p.id ? "border-amber-500/50 bg-amber-500/5" : "border-border/60"}`}
              onClick={() => onSelect(p.id)}
            >
              <CardContent className="py-3 flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <p className="font-medium text-sm">{p.name}</p>
                  <div className="flex flex-wrap gap-1 mt-1">
                    <Badge variant="outline" className="text-[10px]">
                      {BOUNTY_PLATFORM_LABELS[p.platform]}
                    </Badge>
                    <Badge variant="secondary" className="text-[10px]">
                      {p.inScope.length} in-scope
                    </Badge>
                  </div>
                </div>
                <div className="flex gap-1 shrink-0">
                  {p.platformUrl && (
                    <Button size="icon" variant="ghost" className="h-7 w-7" asChild onClick={(e) => e.stopPropagation()}>
                      <a href={p.platformUrl} target="_blank" rel="noopener noreferrer">
                        <ExternalLink className="h-3.5 w-3.5" />
                      </a>
                    </Button>
                  )}
                  <Button size="icon" variant="ghost" className="h-7 w-7" onClick={(e) => { e.stopPropagation(); startEdit(p); }}>
                    Edit
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 text-red-400"
                    onClick={(e) => { e.stopPropagation(); void onDelete(p.id); }}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {editing && (
        <Card className="border-amber-500/25">
          <CardHeader>
            <CardTitle className="text-base">
              {editing === "new" ? "New program" : "Edit program"}
            </CardTitle>
            <CardDescription>Scope rules are enforced during hunts.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="space-y-1">
              <Label className="text-xs">Program name</Label>
              <Input value={name} onChange={(e) => setName(e.target.value)} placeholder="Acme Corp BB" />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">Platform</Label>
                <Select value={platform} onValueChange={(v) => setPlatform(v as BountyPlatform)}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {PLATFORMS.map((pl) => (
                      <SelectItem key={pl} value={pl}>{BOUNTY_PLATFORM_LABELS[pl]}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Program URL</Label>
                <Input value={platformUrl} onChange={(e) => setPlatformUrl(e.target.value)} placeholder="https://hackerone.com/…" />
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-xs flex items-center gap-1">
                <Target className="h-3 w-3" /> In-scope (one per line, *.domain.com)
              </Label>
              <Textarea rows={4} value={inScope} onChange={(e) => setInScope(e.target.value)} className="font-mono text-xs" />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Out-of-scope</Label>
              <Textarea rows={2} value={outOfScope} onChange={(e) => setOutOfScope(e.target.value)} className="font-mono text-xs" />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Notes (rules, rewards table)</Label>
              <Textarea rows={2} value={notes} onChange={(e) => setNotes(e.target.value)} className="text-xs" />
            </div>
            <div className="flex gap-2">
              <Button onClick={() => void submit()}>Save program</Button>
              <Button variant="outline" onClick={resetForm}>Cancel</Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
