/**
 * Bug bounty submission report templates — HackerOne / Bugcrowd compatible markdown.
 */
import type { BountyFinding, BountyProgram } from "@/lib/redteam/bounty-store";
import { BOUNTY_PLATFORM_LABELS } from "@/lib/redteam/bounty-store";

export type ReportFormat = "hackerone" | "bugcrowd" | "generic";

export function buildBountySubmissionReport(
  finding: BountyFinding,
  program: BountyProgram | null,
  format: ReportFormat = "generic",
): string {
  const platform = program ? BOUNTY_PLATFORM_LABELS[program.platform] : "Bug Bounty";
  const lines: string[] = [];

  if (format === "hackerone") {
    lines.push(
      `# ${finding.title}`,
      "",
      "## Summary",
      finding.description || "_Add a clear summary of the vulnerability._",
      "",
      "## Steps To Reproduce",
      finding.stepsToReproduce || "_Numbered reproduction steps._",
      "",
      "## Impact",
      finding.impact || "_Describe business and security impact._",
      "",
      "## Supporting Material / References",
      finding.evidence || "_Screenshots, HTTP requests, responses._",
      "",
      "## Suggested Fix",
      finding.remediation || "_Remediation guidance._",
      "",
      "---",
      `**Severity:** ${finding.severity.toUpperCase()}`,
      `**Asset:** ${finding.target}`,
      `**Type:** ${finding.vulnType}`,
      program ? `**Program:** ${program.name} (${platform})` : "",
    );
  } else if (format === "bugcrowd") {
    lines.push(
      `# Vulnerability Report`,
      "",
      `**Program:** ${program?.name ?? "—"} (${platform})`,
      `**Target:** ${finding.target}`,
      `**VRT / Severity:** ${finding.severity.toUpperCase()} — ${finding.vulnType}`,
      "",
      "## Description",
      finding.description,
      "",
      "## Proof of Concept",
      finding.evidence,
      "",
      "## Steps to Replicate",
      finding.stepsToReproduce,
      "",
      "## Impact",
      finding.impact,
      "",
      "## Recommended Fix",
      finding.remediation,
    );
  } else {
    lines.push(
      `# Bug Bounty Report — ${finding.title}`,
      "",
      `| Field | Value |`,
      `|-------|-------|`,
      `| Program | ${program?.name ?? "—"} |`,
      `| Platform | ${platform} |`,
      `| Target | ${finding.target} |`,
      `| Severity | ${finding.severity} |`,
      `| Type | ${finding.vulnType} |`,
      `| Status | ${finding.status} |`,
      "",
      "## Description",
      finding.description,
      "",
      "## Steps to Reproduce",
      finding.stepsToReproduce,
      "",
      "## Impact",
      finding.impact,
      "",
      "## Evidence",
      finding.evidence,
      "",
      "## Remediation",
      finding.remediation,
    );
  }

  return lines.filter((l) => l !== "").join("\n");
}

export function downloadBountyReport(
  finding: BountyFinding,
  program: BountyProgram | null,
  format: ReportFormat = "generic",
): void {
  const md = buildBountySubmissionReport(finding, program, format);
  const slug = finding.title.replace(/[^a-z0-9]+/gi, "-").slice(0, 40);
  const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `bounty-report-${slug}.md`;
  a.click();
  URL.revokeObjectURL(url);
}
