/**
 * Bug Bounty Hunter — programs, findings, earnings (user data only, no hardcoded stats).
 */
import { supabase } from "@/integrations/supabase/client";
import { currentUserEmail } from "@/lib/auth-adapter";
import { shouldWriteSupabase } from "@/lib/free-storage";
import { generateId } from "@/lib/utils";
import type { PentestFinding, PentestReport } from "@/lib/redteam/pentest-types";

export type BountyPlatform =
  | "hackerone"
  | "bugcrowd"
  | "intigriti"
  | "yeswehack"
  | "synack"
  | "self"
  | "other";

export type BountyFindingStatus =
  | "discovered"
  | "validating"
  | "report-ready"
  | "submitted"
  | "triaged"
  | "accepted"
  | "paid"
  | "duplicate"
  | "informative"
  | "wont-fix";

export type BountyProgram = {
  id: string;
  name: string;
  platform: BountyPlatform;
  platformUrl: string;
  inScope: string[];
  outOfScope: string[];
  notes: string;
  createdAt: string;
  updatedAt: string;
};

export type BountyFinding = {
  id: string;
  programId: string;
  title: string;
  severity: "critical" | "high" | "medium" | "low" | "info";
  vulnType: string;
  status: BountyFindingStatus;
  target: string;
  description: string;
  stepsToReproduce: string;
  impact: string;
  evidence: string;
  remediation: string;
  bountyEstimate: number | null;
  bountyPaid: number | null;
  reportedAt: string | null;
  paidAt: string | null;
  platformTicketId: string;
  scanId: string | null;
  createdAt: string;
  updatedAt: string;
};

export type BountyHunterStats = {
  programs: number;
  totalFindings: number;
  criticalOpen: number;
  highOpen: number;
  submitted: number;
  accepted: number;
  paid: number;
  earningsUsd: number;
  pipelineUsd: number;
};

const STORE_KEY = "threatlens_bounty_hunter_v1";

type LocalStore = {
  programs: BountyProgram[];
  findings: BountyFinding[];
};

function emptyStore(): LocalStore {
  return { programs: [], findings: [] };
}

function readLocal(): LocalStore {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (!raw) return emptyStore();
    const parsed = JSON.parse(raw) as LocalStore;
    return {
      programs: parsed.programs ?? [],
      findings: parsed.findings ?? [],
    };
  } catch {
    return emptyStore();
  }
}

function writeLocal(store: LocalStore): void {
  localStorage.setItem(STORE_KEY, JSON.stringify(store));
}

export const BOUNTY_PLATFORM_LABELS: Record<BountyPlatform, string> = {
  hackerone: "HackerOne",
  bugcrowd: "Bugcrowd",
  intigriti: "Intigriti",
  yeswehack: "YesWeHack",
  synack: "Synack",
  self: "Private / Self",
  other: "Other",
};

export const BOUNTY_STATUS_LABELS: Record<BountyFindingStatus, string> = {
  discovered: "Discovered",
  validating: "Validating",
  "report-ready": "Report ready",
  submitted: "Submitted",
  triaged: "Triaged",
  accepted: "Accepted",
  paid: "Paid",
  duplicate: "Duplicate",
  informative: "Informative",
  "wont-fix": "Won't fix",
};

export function computeBountyStats(
  programs: BountyProgram[],
  findings: BountyFinding[],
): BountyHunterStats {
  const openStatuses = new Set<BountyFindingStatus>([
    "discovered",
    "validating",
    "report-ready",
    "submitted",
    "triaged",
    "accepted",
  ]);
  const criticalOpen = findings.filter(
    (f) => f.severity === "critical" && openStatuses.has(f.status),
  ).length;
  const highOpen = findings.filter(
    (f) => f.severity === "high" && openStatuses.has(f.status),
  ).length;
  const submitted = findings.filter((f) =>
    ["submitted", "triaged", "accepted", "paid"].includes(f.status),
  ).length;
  const accepted = findings.filter((f) => ["accepted", "paid"].includes(f.status)).length;
  const paid = findings.filter((f) => f.status === "paid").length;
  const earningsUsd = findings
    .filter((f) => f.status === "paid" && f.bountyPaid != null)
    .reduce((sum, f) => sum + (f.bountyPaid ?? 0), 0);
  const pipelineUsd = findings
    .filter((f) => ["submitted", "triaged", "accepted"].includes(f.status))
    .reduce((sum, f) => sum + (f.bountyEstimate ?? 0), 0);

  return {
    programs: programs.length,
    totalFindings: findings.length,
    criticalOpen,
    highOpen,
    submitted,
    accepted,
    paid,
    earningsUsd,
    pipelineUsd,
  };
}

function mapDbProgram(row: Record<string, unknown>): BountyProgram {
  return {
    id: String(row.id),
    name: String(row.name ?? ""),
    platform: (row.platform as BountyPlatform) ?? "other",
    platformUrl: String(row.platform_url ?? ""),
    inScope: (row.in_scope as string[]) ?? [],
    outOfScope: (row.out_of_scope as string[]) ?? [],
    notes: String(row.notes ?? ""),
    createdAt: String(row.created_at ?? new Date().toISOString()),
    updatedAt: String(row.updated_at ?? new Date().toISOString()),
  };
}

function mapDbFinding(row: Record<string, unknown>): BountyFinding {
  return {
    id: String(row.id),
    programId: String(row.program_id),
    title: String(row.title ?? ""),
    severity: (row.severity as BountyFinding["severity"]) ?? "medium",
    vulnType: String(row.vuln_type ?? ""),
    status: (row.status as BountyFindingStatus) ?? "discovered",
    target: String(row.target ?? ""),
    description: String(row.description ?? ""),
    stepsToReproduce: String(row.steps_to_reproduce ?? ""),
    impact: String(row.impact ?? ""),
    evidence: String(row.evidence ?? ""),
    remediation: String(row.remediation ?? ""),
    bountyEstimate: row.bounty_estimate != null ? Number(row.bounty_estimate) : null,
    bountyPaid: row.bounty_paid != null ? Number(row.bounty_paid) : null,
    reportedAt: row.reported_at ? String(row.reported_at) : null,
    paidAt: row.paid_at ? String(row.paid_at) : null,
    platformTicketId: String(row.platform_ticket_id ?? ""),
    scanId: row.scan_id ? String(row.scan_id) : null,
    createdAt: String(row.created_at ?? new Date().toISOString()),
    updatedAt: String(row.updated_at ?? new Date().toISOString()),
  };
}

async function tryLoadCloud(): Promise<LocalStore | null> {
  if (!shouldWriteSupabase()) return null;
  const email = currentUserEmail();
  if (!email) return null;
  try {
    const [progRes, findRes] = await Promise.all([
      supabase.from("bounty_programs").select("*").eq("user_email", email).order("updated_at", { ascending: false }),
      supabase.from("bounty_findings").select("*").eq("user_email", email).order("updated_at", { ascending: false }),
    ]);
    if (progRes.error || findRes.error) return null;
    return {
      programs: (progRes.data ?? []).map(mapDbProgram),
      findings: (findRes.data ?? []).map(mapDbFinding),
    };
  } catch {
    return null;
  }
}

async function persistCloud(store: LocalStore): Promise<void> {
  if (!shouldWriteSupabase()) return;
  const email = currentUserEmail();
  if (!email) return;
  try {
    await supabase.from("bounty_programs").delete().eq("user_email", email);
    await supabase.from("bounty_findings").delete().eq("user_email", email);
    if (store.programs.length) {
      await supabase.from("bounty_programs").insert(
        store.programs.map((p) => ({
          id: p.id,
          user_email: email,
          name: p.name,
          platform: p.platform,
          platform_url: p.platformUrl,
          in_scope: p.inScope,
          out_of_scope: p.outOfScope,
          notes: p.notes,
          created_at: p.createdAt,
          updated_at: p.updatedAt,
        })),
      );
    }
    if (store.findings.length) {
      await supabase.from("bounty_findings").insert(
        store.findings.map((f) => ({
          id: f.id,
          user_email: email,
          program_id: f.programId,
          title: f.title,
          severity: f.severity,
          vuln_type: f.vulnType,
          status: f.status,
          target: f.target,
          description: f.description,
          steps_to_reproduce: f.stepsToReproduce,
          impact: f.impact,
          evidence: f.evidence,
          remediation: f.remediation,
          bounty_estimate: f.bountyEstimate,
          bounty_paid: f.bountyPaid,
          reported_at: f.reportedAt,
          paid_at: f.paidAt,
          platform_ticket_id: f.platformTicketId,
          scan_id: f.scanId,
          created_at: f.createdAt,
          updated_at: f.updatedAt,
        })),
      );
    }
  } catch {
    /* local-first — cloud sync is best-effort */
  }
}

export async function loadBountyHunterStore(): Promise<LocalStore> {
  const cloud = await tryLoadCloud();
  if (cloud && (cloud.programs.length || cloud.findings.length)) {
    writeLocal(cloud);
    return cloud;
  }
  return readLocal();
}

async function saveStore(store: LocalStore): Promise<void> {
  writeLocal(store);
  await persistCloud(store);
}

export async function upsertBountyProgram(
  input: Omit<BountyProgram, "id" | "createdAt" | "updatedAt"> & { id?: string },
): Promise<BountyProgram> {
  const store = readLocal();
  const now = new Date().toISOString();
  const program: BountyProgram = {
    id: input.id ?? generateId(),
    name: input.name.trim(),
    platform: input.platform,
    platformUrl: input.platformUrl.trim(),
    inScope: input.inScope.map((s) => s.trim()).filter(Boolean),
    outOfScope: input.outOfScope.map((s) => s.trim()).filter(Boolean),
    notes: input.notes.trim(),
    createdAt: input.id ? store.programs.find((p) => p.id === input.id)?.createdAt ?? now : now,
    updatedAt: now,
  };
  const idx = store.programs.findIndex((p) => p.id === program.id);
  if (idx >= 0) store.programs[idx] = program;
  else store.programs.unshift(program);
  await saveStore(store);
  return program;
}

export async function deleteBountyProgram(id: string): Promise<void> {
  const store = readLocal();
  store.programs = store.programs.filter((p) => p.id !== id);
  store.findings = store.findings.filter((f) => f.programId !== id);
  await saveStore(store);
}

export async function upsertBountyFinding(
  input: Omit<BountyFinding, "id" | "createdAt" | "updatedAt"> & { id?: string },
): Promise<BountyFinding> {
  const store = readLocal();
  const now = new Date().toISOString();
  const finding: BountyFinding = {
    id: input.id ?? generateId(),
    programId: input.programId,
    title: input.title.trim(),
    severity: input.severity,
    vulnType: input.vulnType.trim(),
    status: input.status,
    target: input.target.trim(),
    description: input.description.trim(),
    stepsToReproduce: input.stepsToReproduce.trim(),
    impact: input.impact.trim(),
    evidence: input.evidence.trim(),
    remediation: input.remediation.trim(),
    bountyEstimate: input.bountyEstimate,
    bountyPaid: input.bountyPaid,
    reportedAt: input.reportedAt,
    paidAt: input.paidAt,
    platformTicketId: input.platformTicketId.trim(),
    scanId: input.scanId,
    createdAt: input.id ? store.findings.find((f) => f.id === input.id)?.createdAt ?? now : now,
    updatedAt: now,
  };
  const idx = store.findings.findIndex((f) => f.id === finding.id);
  if (idx >= 0) store.findings[idx] = finding;
  else store.findings.unshift(finding);
  await saveStore(store);
  return finding;
}

export async function deleteBountyFinding(id: string): Promise<void> {
  const store = readLocal();
  store.findings = store.findings.filter((f) => f.id !== id);
  await saveStore(store);
}

export function isTargetInScope(target: string, inScope: string[]): boolean | null {
  if (!target.trim() || !inScope.length) return null;
  const host = target.replace(/^https?:\/\//, "").split("/")[0].toLowerCase();
  return inScope.some((s) => {
    const pattern = s.toLowerCase().replace(/^\*\./, "");
    return host === pattern || host.endsWith(`.${pattern}`) || host.includes(pattern);
  });
}

export function pentestFindingToBounty(
  f: PentestFinding,
  programId: string,
  report: PentestReport,
): Omit<BountyFinding, "id" | "createdAt" | "updatedAt"> {
  return {
    programId,
    title: f.title,
    severity: f.severity === "info" ? "info" : f.severity,
    vulnType: f.category || f.owasp || "Web",
    status: f.severity === "critical" || f.severity === "high" ? "validating" : "discovered",
    target: f.affectedAsset || report.target,
    description: f.description,
    stepsToReproduce: `1. Navigate to ${f.affectedAsset || report.finalUrl}\n2. Observe: ${f.title}\n3. Evidence: ${f.evidence}`,
    impact: f.severity === "critical"
      ? "Critical impact — potential full compromise, data breach, or account takeover."
      : f.severity === "high"
        ? "High impact — significant security boundary violation."
        : "Review impact against program policy and Bugcrowd VRT.",
    evidence: f.evidence,
    remediation: f.recommendation,
    bountyEstimate: severityBountyEstimate(f.severity),
    bountyPaid: null,
    reportedAt: null,
    paidAt: null,
    platformTicketId: "",
    scanId: report.scanId,
  };
}

/** Rough VRT-aligned estimates for planning — user overrides when reporting. */
export function severityBountyEstimate(severity: PentestFinding["severity"]): number | null {
  switch (severity) {
    case "critical": return 2500;
    case "high": return 750;
    case "medium": return 250;
    case "low": return 100;
    default: return null;
  }
}

export async function importCriticalFromReport(
  report: PentestReport,
  programId: string,
  minSeverity: "critical" | "high" = "high",
): Promise<BountyFinding[]> {
  const order = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };
  const threshold = order[minSeverity];
  const eligible = report.findings.filter((f) => order[f.severity] <= threshold);
  const created: BountyFinding[] = [];
  for (const f of eligible) {
    const finding = await upsertBountyFinding(pentestFindingToBounty(f, programId, report));
    created.push(finding);
  }
  return created;
}
