import { useCallback, useEffect, useState } from "react";
import {
  loadBountyHunterStore,
  computeBountyStats,
  upsertBountyProgram,
  deleteBountyProgram,
  upsertBountyFinding,
  deleteBountyFinding,
  importCriticalFromReport,
  type BountyProgram,
  type BountyFinding,
  type BountyHunterStats,
} from "@/lib/redteam/bounty-store";
import type { PentestReport } from "@/lib/redteam/pentest-types";

export function useBountyHunter() {
  const [programs, setPrograms] = useState<BountyProgram[]>([]);
  const [findings, setFindings] = useState<BountyFinding[]>([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<BountyHunterStats>(computeBountyStats([], []));

  const refresh = useCallback(async () => {
    setLoading(true);
    const store = await loadBountyHunterStore();
    setPrograms(store.programs);
    setFindings(store.findings);
    setStats(computeBountyStats(store.programs, store.findings));
    setLoading(false);
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const saveProgram = useCallback(
    async (input: Parameters<typeof upsertBountyProgram>[0]) => {
      const p = await upsertBountyProgram(input);
      await refresh();
      return p;
    },
    [refresh],
  );

  const removeProgram = useCallback(
    async (id: string) => {
      await deleteBountyProgram(id);
      await refresh();
    },
    [refresh],
  );

  const saveFinding = useCallback(
    async (input: Parameters<typeof upsertBountyFinding>[0]) => {
      const f = await upsertBountyFinding(input);
      await refresh();
      return f;
    },
    [refresh],
  );

  const removeFinding = useCallback(
    async (id: string) => {
      await deleteBountyFinding(id);
      await refresh();
    },
    [refresh],
  );

  const importFromScan = useCallback(
    async (report: PentestReport, programId: string, minSeverity: "critical" | "high" = "high") => {
      const created = await importCriticalFromReport(report, programId, minSeverity);
      await refresh();
      return created;
    },
    [refresh],
  );

  return {
    programs,
    findings,
    stats,
    loading,
    refresh,
    saveProgram,
    removeProgram,
    saveFinding,
    removeFinding,
    importFromScan,
  };
}
